 readonly string root;readonly ClaudeSource source;readonly AnimatedPortrait art=new AnimatedPortrait();readonly Dictionary<string,BitmapImage> images=new Dictionary<string,BitmapImage>();readonly TextBlock status=new TextBlock(),actual=new TextBlock(),target=new TextBlock();readonly Slider slider=new Slider{Minimum=0,Maximum=5,TickFrequency=1,IsSnapToTickEnabled=true,Width=260};readonly ComboBox chats=new ComboBox{Width=265,MaxDropDownHeight=230};readonly CheckBox follow=new CheckBox{Content="自动跟随 Claude 当前 Code 聊天",IsChecked=true};readonly Button resume=new Button{Content="结束预览 · 恢复只读跟随",Margin=new Thickness(0,5,0,0)};readonly DispatcherTimer timer=new DispatcherTimer();readonly SemaphoreSlim gate=new SemaphoreSlim(1,1);ClaudeHost host=new ClaudeHost();DateTime nextHost=DateTime.MinValue;string form="",manualId,lastFocus="",chatStamp="",stateStamp="";bool preview,updating,closing,economy,locked;Point down;double originalLeft,originalTop;bool pressed,dragged;readonly bool export,previewOnly;
