 public XiaoKeWindow(string path,string dataRoot,bool exportMode,bool previewMode){previewOnly=previewMode;root=path;source=new ClaudeSource(dataRoot);export=exportMode;Title="Claude 小克娘 · 只读动态";Resources=Theme.Create();Width=340;Height=590;WindowStyle=WindowStyle.None;ResizeMode=ResizeMode.NoResize;AllowsTransparency=true;Background=Brushes.Transparent;ShowInTaskbar=false;ShowActivated=false;Topmost=true;FontFamily=new FontFamily("Microsoft YaHei UI");Left=30;Top=Math.Max(0,SystemParameters.WorkArea.Bottom-Height-25);ReadOwn();
