  var grid=new Grid{Margin=new Thickness(7)};grid.RowDefinitions.Add(new RowDefinition{Height=new GridLength(1,GridUnitType.Star)});grid.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});art.Margin=new Thickness(8,0,8,0);grid.Children.Add(art);var panel=new StackPanel();status.TextAlignment=TextAlignment.Center;status.FontWeight=FontWeights.SemiBold;status.Foreground=new SolidColorBrush(Color.FromRgb(126,74,40));status.FontSize=13;status.Text="只读 · 等待 Claude";actual.FontSize=11;actual.TextAlignment=TextAlignment.Center;actual.Foreground=Brushes.SaddleBrown;target.FontSize=10;target.TextAlignment=TextAlignment.Center;target.TextTrimming=TextTrimming.CharacterEllipsis;target.Margin=new Thickness(0,3,0,4);panel.Children.Add(status);panel.Children.Add(actual);actual.Visibility=Visibility.Collapsed;panel.Children.Add(target);panel.Children.Add(slider);var ticks=new System.Windows.Controls.Primitives.UniformGrid{Columns=6,Margin=new Thickness(0,-2,0,4)};foreach(string label in new[]{"Low","中","高","Extra","Max","Ultra"})ticks.Children.Add(new TextBlock{Text=label,FontSize=9,Foreground=new SolidColorBrush(Color.FromRgb(166,125,75)),TextAlignment=TextAlignment.Center});panel.Children.Add(ticks);panel.Children.Add(new TextBlock{Text="滑块仅预览动画，不改变 Claude 思考档位",FontSize=10,TextAlignment=TextAlignment.Center,Foreground=Brushes.Gray});panel.Children.Add(resume);follow.Margin=new Thickness(0,6,0,4);var options=new StackPanel();options.Children.Add(follow);options.Children.Add(chats);panel.Children.Add(new Expander{Header="跟随与聊天选择",FontSize=10,Foreground=Brushes.Sienna,Margin=new Thickness(0,5,0,0),Content=options});var border=new Border{Child=panel,CornerRadius=new CornerRadius(22),Background=new SolidColorBrush(Color.FromRgb(255,250,240)),BorderBrush=new SolidColorBrush(Color.FromRgb(230,194,135)),BorderThickness=new Thickness(1),Padding=new Thickness(17,11,17,10),HorizontalAlignment=HorizontalAlignment.Center};Grid.SetRow(border,1);grid.Children.Add(border);Content=grid;resume.Visibility=Visibility.Collapsed;SetForm(0);if(previewOnly){preview=true;resume.IsEnabled=false;follow.IsChecked=false;follow.IsEnabled=false;chats.IsEnabled=false;status.Text="动画预览 · Low（不连接 Claude）";actual.Text="仅预览画面，不修改任何档位";ShowInTaskbar=true;}
