 }
 void SetForm(int index){if(index<0||index>5)return;string key=ClaudeForms.Keys[index];if(form!=key){art.Form=key;art.Source=images[key];form=key;}art.Opacity=1;}
 async Task Tick(){if(closing||!await gate.WaitAsync(0))return;try{if(previewOnly){Opacity=1;IsHitTestVisible=true;return;}if(DateTime.UtcNow>=nextHost){host=await Task.Run(()=>ClaudeHost.Scan());nextHost=DateTime.UtcNow.AddSeconds(2);}if(closing)return;Opacity=host.Visible?1:0;IsHitTestVisible=host.Visible;if(!host.Visible){await Task.Run(()=>source.Update("",DateTime.MinValue));WriteState(null,-1,follow.IsChecked==true);return;}await Task.Run(()=>source.Update(host.Identity,host.StartedUtc));if(closing)return;
  string stamp=String.Join("|",source.Entries.Select(e=>e.Id+e.Title));if(stamp!=chatStamp){chatStamp=stamp;updating=true;chats.ItemsSource=source.Entries;chats.SelectedItem=source.Entries.Find(e=>e.Id==manualId);updating=false;}
  bool auto=follow.IsChecked==true;string id=auto?(source.FocusKnown?source.FocusId:null):manualId;if(auto&&id!=lastFocus){lastFocus=id;preview=false;}var entry=id==null?null:await Task.Run(()=>source.ReadSelected(id));if(closing)return;int tier=entry==null?-1:ClaudeForms.Index(entry.Effort,entry.Ultra);actual.Text=tier<0?"Claude 实际档位：未识别":"Claude 实际档位："+ClaudeForms.Labels[tier];target.Text=entry==null?(auto?source.Hint:"请选择目标聊天"):entry.Title;
  if(!preview){if(tier>=0){SetForm(tier);status.Text=(auto?"只读跟随 · ":"手动跟随 · ")+ClaudeForms.Labels[tier];updating=true;slider.Value=tier;updating=false;}else{SetForm(0);status.Text="只读 · "+(auto?source.Hint:"等待目标聊天");art.Opacity=.70;}}
  resume.Visibility=preview?Visibility.Visible:Visibility.Collapsed;actual.Visibility=preview?Visibility.Visible:Visibility.Collapsed;resume.IsEnabled=preview;WriteState(entry,tier,auto);
 }catch{status.Text="只读 · 状态暂不可读";actual.Text="不会修改 Claude 设置";}finally{gate.Release();}}
 void WriteState(ClaudeEntry entry,int tier,bool auto){string stamp=(entry==null?"":entry.Id)+"/"+tier+"/"+auto+"/"+preview+"/"+form+"/"+source.Hint;if(stamp==stateStamp)return;try{string dir=Path.Combine(root,"runtime");Directory.CreateDirectory(dir);string file=Path.Combine(dir,"display-state.json"),tmp=file+".tmp";File.WriteAllText(tmp,Json.Encode(new{version="1.1.0",readOnly=true,metadataSource="Claude session metadata + focused-session log",connected=tier>=0,sessionId=entry==null?null:entry.Id,effort=entry==null?null:entry.Effort,ultracode=entry!=null&&entry.Ultra,preview=preview,form=form,autoFollow=auto,hint=source.Hint,utc=DateTime.UtcNow.ToString("O")}));if(File.Exists(file))File.Replace(tmp,file,null);else File.Move(tmp,file);stateStamp=stamp;}catch{}}
 void Press(object s,MouseButtonEventArgs e){pressed=true;dragged=false;down=PointToScreen(e.GetPosition(this));originalLeft=Left;originalTop=Top;art.CaptureMouse();e.Handled=true;}
 void Move(object s,MouseEventArgs e){if(!pressed||locked||e.LeftButton!=MouseButtonState.Pressed)return;var delta=PointToScreen(e.GetPosition(this))-down;if(!dragged&&delta.Length<6)return;dragged=true;var p=PresentationSource.FromVisual(this);if(p!=null)delta=p.CompositionTarget.TransformFromDevice.Transform(delta);Left=originalLeft+delta.X;Top=originalTop+delta.Y;}
 void Release(object s,MouseButtonEventArgs e){if(!pressed)return;pressed=false;art.ReleaseMouseCapture();if(dragged){Clamp();SaveOwn();}else art.React();e.Handled=true;}
 void Menu(){var menu=new ContextMenu();var title=new MenuItem{Header="小克娘 · 只读，不修改 Claude",IsEnabled=false};menu.Items.Add(title);var low=new MenuItem{Header="省电模式",IsCheckable=true,IsChecked=economy};low.Click+=(s,e)=>{economy=!economy;art.EconomyMode=economy;SaveOwn();};menu.Items.Add(low);var pin=new MenuItem{Header="锁定位置",IsCheckable=true,IsChecked=locked};pin.Click+=(s,e)=>{locked=!locked;SaveOwn();};menu.Items.Add(pin);var exit=new MenuItem{Header="退出小克娘"};exit.Click+=(s,e)=>Close();menu.Items.Add(exit);menu.PlacementTarget=slider;menu.IsOpen=true;}
 void Clamp(){var area=SystemParameters.WorkArea;if(Left<area.Left||Left+Width>area.Right)Left=area.Left+20;if(Top<area.Top||Top+Height>area.Bottom)Top=Math.Max(area.Top,area.Bottom-Height-15);}
 void ReadOwn(){try{var d=Json.Decode(File.ReadAllText(Path.Combine(root,"runtime","settings.json")));object n=Json.Get(d,"left");if(n!=null)Left=Convert.ToDouble(n);n=Json.Get(d,"top");if(n!=null)Top=Convert.ToDouble(n);economy=true.Equals(Json.Get(d,"economy"));locked=true.Equals(Json.Get(d,"locked"));art.EconomyMode=economy;}catch{}}
 void SaveOwn(){if(export||previewOnly)return;try{string dir=Path.Combine(root,"runtime");Directory.CreateDirectory(dir);File.WriteAllText(Path.Combine(dir,"settings.json"),Json.Encode(new{left=Left,top=Top,economy=economy,locked=locked}));}catch{}}
 void RenderAll(){var output=Path.Combine(root,"verification");Directory.CreateDirectory(output);foreach(string key in ClaudeForms.Keys){SetForm(Array.IndexOf(ClaudeForms.Keys,key));updating=true;slider.Value=Array.IndexOf(ClaudeForms.Keys,key);updating=false;status.Text=ClaudeForms.Labels[Array.IndexOf(ClaudeForms.Keys,key)];actual.Text="仅显示动画，不改变 Claude";Measure(new Size(Width,Height));Arrange(new Rect(0,0,Width,Height));UpdateLayout();art.Step(1.7);var b=new RenderTargetBitmap((int)Width,(int)Height,96,96,PixelFormats.Pbgra32);b.Render(this);var enc=new PngBitmapEncoder();enc.Frames.Add(BitmapFrame.Create(b));using(var f=File.Create(Path.Combine(output,"preview-"+key+".png")))enc.Save(f);}}
